import{_ as s,o as i,c as t,a1 as a}from"./chunks/framework.DdbKPUhY.js";const k=JSON.parse(`{"title":"Memory Safety — ASan & UBSan Verified","description":"UVHTTP's memory-safety guarantee: the full 91-test suite is verified clean under AddressSanitizer and UndefinedBehaviorSanitizer, nightly in CI, reproducible with one command. Bug classes fixed, defense in depth, and why it matters for long-running and embedded deployments.","frontmatter":{"title":"Memory Safety — ASan & UBSan Verified","description":"UVHTTP's memory-safety guarantee: the full 91-test suite is verified clean under AddressSanitizer and UndefinedBehaviorSanitizer, nightly in CI, reproducible with one command. Bug classes fixed, defense in depth, and why it matters for long-running and embedded deployments."},"headers":[],"relativePath":"MEMORY_SAFETY.md","filePath":"MEMORY_SAFETY.md"}`),n={name:"MEMORY_SAFETY.md"};function r(d,e,l,o,h,p){return i(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="memory-safety" tabindex="-1">Memory Safety <a class="header-anchor" href="#memory-safety" aria-label="Permalink to &quot;Memory Safety&quot;">​</a></h1><p>UVHTTP&#39;s headline differentiator is not peak single-host throughput (nginx and h2o win there) — it is <strong>verified memory safety in a lightweight, embeddable, 32-bit-capable C library</strong>. For long-running production services and embedded devices that cannot tolerate a slow memory leak or a use-after-free after weeks of uptime, this is the property that matters, and it is the one most comparable lightweight C HTTP libraries do not provide.</p><p>This document is the engineering evidence.</p><h2 id="the-guarantee" tabindex="-1">The guarantee <a class="header-anchor" href="#the-guarantee" aria-label="Permalink to &quot;The guarantee&quot;">​</a></h2><p>The full 91-test suite is verified clean under <strong>both</strong>:</p><table tabindex="0"><thead><tr><th>Sanitizer</th><th>What it catches</th><th>Result</th></tr></thead><tbody><tr><td><strong>AddressSanitizer</strong> (with leak detection)</td><td>heap use-after-free, heap-buffer-overflow, stack-buffer-overflow, memory leaks</td><td><strong>91/91 pass, zero findings</strong></td></tr><tr><td><strong>UndefinedBehaviorSanitizer</strong></td><td>signed integer overflow, invalid shifts, null dereference, misalignment, out-of-bounds</td><td><strong>91/91 pass, zero findings</strong></td></tr></tbody></table><p>ASan and UBSan cannot be combined in a single build, so they run as two separate configurations. Both must be green.</p><h2 id="reproduce-it-yourself-one-command" tabindex="-1">Reproduce it yourself (one command) <a class="header-anchor" href="#reproduce-it-yourself-one-command" aria-label="Permalink to &quot;Reproduce it yourself (one command)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify-memory-safety</span></span></code></pre></div><p>This configures and builds the suite under ASan and UBSan, runs the full 91-test suite under each, and exits non-zero if any test fails or any sanitizer reports a finding. A clean run prints:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>==&gt; PASS: full suite clean under ASan and UBSan (91/91 each).</span></span></code></pre></div><p>The equivalent manual commands:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># AddressSanitizer (leaks, use-after-free, overflows)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build_asan</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DCMAKE_BUILD_TYPE=Debug</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DENABLE_ASAN=ON</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build_asan</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -j$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nproc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build_asan</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ctest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output-on-failure</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># UndefinedBehaviorSanitizer</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build_ubsan</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DCMAKE_BUILD_TYPE=Debug</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DENABLE_UBSAN=ON</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build_ubsan</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -j$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nproc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build_ubsan</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ctest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output-on-failure</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Sanitizer builds keep debug symbols (no <code>-s</code> strip) so any finding produces a resolvable, source-level stack trace.</p><h2 id="continuous-verification" tabindex="-1">Continuous verification <a class="header-anchor" href="#continuous-verification" aria-label="Permalink to &quot;Continuous verification&quot;">​</a></h2><p>Memory safety is a <strong>non-regressing invariant</strong>, not a one-time check:</p><ul><li><strong>PR CI gate</strong> (<code>.github/workflows/ci-pr.yml</code>): the <code>asan-gate</code> job runs the suite under ASan on every pull request — memory safety cannot regress into <code>main</code>.</li><li><strong>Nightly CI</strong> (<code>.github/workflows/ci-nightly.yml</code>): the <code>test-memory</code> (ASan with leak detection) and <code>test-ubsan</code> jobs run the full suite under each sanitizer every night.</li><li><strong>Nightly fuzzing</strong> (<code>.github/workflows/ci-fuzz.yml</code>): a libFuzzer harness (<code>test/fuzz/fuzz_router.c</code>) drives the router with millions of arbitrary inputs under ASan — finding bugs the fixed test inputs do not reach (it already found one; see below).</li><li><strong>Build-system guard</strong>: sanitizer/Debug builds are never stripped, so CI findings are always debuggable.</li></ul><h2 id="fuzzing" tabindex="-1">Fuzzing <a class="header-anchor" href="#fuzzing" aria-label="Permalink to &quot;Fuzzing&quot;">​</a></h2><p>Sanitizers cover the code paths the test suite exercises. Fuzzing covers the paths it doesn&#39;t. UVHTTP ships a libFuzzer harness for the router (<code>test/fuzz/fuzz_router.c</code>), run nightly in CI.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Build (clang + libFuzzer + ASan)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build_fuzz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DCMAKE_BUILD_TYPE=Debug</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DENABLE_ASAN=ON</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -DBUILD_TESTING=OFF</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DBUILD_EXAMPLES=OFF</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build_fuzz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -j$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nproc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">)</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uvhttp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">clang</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsanitize=fuzzer,address</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fno-omit-frame-pointer</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -Iinclude</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Ideps/llhttp/include</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Ideps/uthash/src</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -Ideps/mbedtls/include</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Ideps/cjson</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Ideps/libuv/include</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  test/fuzz/fuzz_router.c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build_fuzz/dist/lib/libuvhttp.a</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -Wl,--start-group</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  deps/llhttp/build/libllhttp.a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deps/cjson/build/libcjson.a</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  deps/mbedtls/build/library/libmbedtls.a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deps/mbedtls/build/library/libmbedx509.a</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  deps/mbedtls/build/library/libmbedcrypto.a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deps/libuv/build/libuv.a</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -Wl,--end-group</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lpthread</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ldl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fuzz_router</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./fuzz_router</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -max_total_time=60</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -max_len=256</span></span></code></pre></div><p>A clean run exits 0 with no <code>ERROR:</code> line. The harness already found the <code>add_route_method</code> heap-buffer-overflow listed in the table below (a post-migration non-parameter route registration that the unit tests never performed in that order) — which is exactly the point of fuzzing.</p><h2 id="bug-classes-fixed-to-reach-this-guarantee" tabindex="-1">Bug classes fixed to reach this guarantee <a class="header-anchor" href="#bug-classes-fixed-to-reach-this-guarantee" aria-label="Permalink to &quot;Bug classes fixed to reach this guarantee&quot;">​</a></h2><p>The suite did not start clean. Reaching zero sanitizer findings required fixing genuine memory-safety defects in production library code — bugs that passed the normal test suite but corrupted memory under sanitizers. Representative fixes (full list in the <a href="./guide/CHANGELOG.html">Changelog</a>):</p><table tabindex="0"><thead><tr><th>Bug class</th><th>Location</th><th>Detail</th></tr></thead><tbody><tr><td>heap-buffer-overflow</td><td><code>uvhttp_router.c</code> <code>add_route_method</code></td><td><strong>Found by libFuzzer.</strong> After a parameter route triggered trie migration (resetting <code>array_capacity</code> to 0), a later non-parameter route fell through to <code>add_array_route</code>, whose <code>0*2</code> capacity computed a zero-size realloc that <code>strncpy</code> overflowed. The normal test suite never hit this route-registration order.</td></tr><tr><td>heap-use-after-free</td><td><code>uvhttp_router.c</code> <code>find_or_create_child</code></td><td>cached pointer into node pool dangled after <code>realloc</code> grew the pool</td></tr><tr><td>heap-use-after-free</td><td><code>uvhttp_server.c</code> <code>uvhttp_server_free</code></td><td><code>freed</code> flag read from already-freed memory on double-free</td></tr><tr><td>heap-use-after-free</td><td><code>uvhttp_connection.c</code></td><td>post-close read; <code>close_pending</code> accounting broken on re-entry</td></tr><tr><td>heap-buffer-overflow</td><td><code>uvhttp_response.c</code> <code>build_response_headers</code></td><td><code>snprintf</code> return accumulation let <code>pos</code> exceed the buffer, underflowing the bound</td></tr><tr><td>stack-buffer-underflow</td><td><code>uvhttp_websocket.c</code> <code>uvhttp_ws_close</code></td><td>write to out-of-scope stack connection</td></tr><tr><td>memory leak</td><td><code>uvhttp_connection.c</code> <code>restart_read</code></td><td>request body pointer nulled without freeing</td></tr><tr><td>memory leak</td><td><code>uvhttp_server.c</code> <code>on_connection</code> 503 path</td><td><code>temp_client</code> (<code>uv_tcp_t</code>) never closed/freed</td></tr><tr><td>memory leak</td><td><code>uvhttp_server.c</code> <code>ws_disable_connection_management</code></td><td>manager struct (with embedded <code>uv_timer_t</code>s) freed before close callbacks fired</td></tr><tr><td>memory leak</td><td><code>uvhttp_error_helpers.c</code></td><td><code>uv_strerror</code> on non-libuv errno triggered an unfreeable libuv <code>uv__strdup</code></td></tr><tr><td>undefined behavior</td><td><code>uvhttp_connection.c</code> <code>switch_to_websocket</code></td><td>re-entry clobbered CLOSING state, breaking close accounting (caught as a UBSan-time hang)</td></tr></tbody></table><p>Each was root-caused (not masked) and fixed at the source.</p><h2 id="why-this-matters-and-why-most-lightweight-c-libraries-lack-it" tabindex="-1">Why this matters (and why most lightweight C libraries lack it) <a class="header-anchor" href="#why-this-matters-and-why-most-lightweight-c-libraries-lack-it" aria-label="Permalink to &quot;Why this matters (and why most lightweight C libraries lack it)&quot;">​</a></h2><p>A C HTTP library that &quot;passes its tests&quot; can still leak a few kilobytes per connection, dereference freed memory on a rare close race, or build an unterminated string into a response. None of these fail a functional test. They surface as:</p><ul><li><strong>Slow RSS growth</strong> over days/weeks of uptime (embedded devices cannot restart).</li><li><strong>Intermittent crashes</strong> under load patterns the test suite never hit.</li><li><strong>Security-reachable corruption</strong> (buffer overflows in header/body parsing).</li></ul><p>Sanitizers catch these <em>before</em> deployment. Most lightweight C HTTP libraries do not advertise sanitizer-clean status — not because they are clean, but because they have not run the check. UVHTTP runs it nightly and treats any finding as a release blocker.</p><h2 id="defense-in-depth" tabindex="-1">Defense in depth <a class="header-anchor" href="#defense-in-depth" aria-label="Permalink to &quot;Defense in depth&quot;">​</a></h2><p>Beyond sanitizers, the codebase applies:</p><ul><li><strong><code>-Werror</code></strong> with <code>-Wall -Wextra -Wformat=2 -Wformat-security</code>: zero warnings compile gate.</li><li><strong><code>-fstack-protector-strong</code></strong>, <code>-fno-common</code>, full RELRO (<code>-Wl,-z,relro,now</code>).</li><li><strong>HTTP response-splitting guards</strong> (<code>contains_control_chars</code>) on all header values before emission.</li><li><strong>Input validation</strong>: URL length/path-traversal, header size/format, body size limits.</li><li><strong>Idempotent resource cleanup</strong>: <code>*_cleanup</code>/<code>*_free_resources</code> paths null pointers after freeing and guard on a <code>freed</code> flag to be robust against double-free at the API boundary.</li></ul><h2 id="when-a-sanitizer-finding-is-reported" tabindex="-1">When a sanitizer finding is reported <a class="header-anchor" href="#when-a-sanitizer-finding-is-reported" aria-label="Permalink to &quot;When a sanitizer finding is reported&quot;">​</a></h2><ol><li>Reproduce with <code>make verify-memory-safety</code> (or the specific sanitizer build).</li><li>Root-cause from the source-level stack trace (sanitizer builds are unstripped).</li><li>Fix at the source — do not suppress.</li><li>Confirm both ASan and UBSan are green before merging.</li></ol><p>Report security-relevant findings via the process in <a href="./guide/SECURITY.html">SECURITY.md</a>.</p>`,35)])])}const u=s(n,[["render",r]]);export{k as __pageData,u as default};
